function reset(quick=false){if((RecruitRun.get(RecruitRun.mainKey)?.releaseComplete===false&&!DebugMode.enabled)||!SkillArt.isReady(RecruitRun.mainKey)||!SkillArt.loaded(RecruitRun.mainKey))return;if(!assetsReady||(quick&&!DebugMode.enabled))return;SkillArt.clear();UltimateCue.clear();BuildInspect.close(false);SkillLab.closeDock();document.body.dataset.home='false';fitBattle();$('shell').appendChild($('modal'));$('modal').classList.remove('choice-screen','squad-pause','beast-hatch');if($('rosterOverlay'))$('rosterOverlay').hidden=true;clearTimeout(toastTimer);$('battleToast').classList.remove('show');s=idleState();s.debugUsed=RecruitRun.get(s.mainKey).releaseComplete===false;s.quick=quick;s.t=quick?780:0;s.level=quick?12:1;s.form=RecruitRun.get(s.mainKey).sprite;s.ras=quick?4:1;s.clone=quick?2:1;s.haste=quick?1:0;s.need=levelNeed(s.level);keys={};release();state='play';$('startOverlay').hidden=true;$('modal').hidden=true;document.body.dataset.playing='true';if(quick){s.bossStep=2;s.bossLedger=['skipped','skipped','pending'];s.nextBossAt=s.t;s.debugUsed=true;spawnBoss()}else toast(s.debugUsed?'调试预览局 / 演出待校正，不计战绩':'单人试炼 / 升级招募，最多3名支援');updateHud()}
function sound(f=440,d=.08){if(muted)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(40,f*.5),audio.currentTime+d);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.type='square';o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch{}}
